# area: abstract_classes
# hypothesis: In a diamond of ABCs, an abstract method inherited first through the left base shadows a concrete override in the right base, so the bottom class stays abstract and cannot be instantiated, while register() adds only a virtual subclass.
from abc import ABC, abstractmethod
from typing import reveal_type


class Base(ABC):
    @property
    @abstractmethod
    def name(self) -> str:
        raise NotImplementedError


class Left(Base):
    @abstractmethod
    def size(self) -> int:
        raise NotImplementedError


class Right(Base):
    @property
    def name(self) -> str:
        return 'right'

    def size(self) -> int:
        return 3


class Bottom(Left, Right):
    pass


class Complete(Bottom):
    def size(self) -> int:
        return 5


class Registered:
    pass


Base.register(Registered)

partial: Bottom | None = None
try:
    partial = Bottom()  # expect-error
except TypeError:
    pass

full = Complete()
reveal_type(full.name)
reveal_type(full.size())
assert full.name == 'right'
assert full.size() == 5
assert partial is None
reg = Registered()
assert isinstance(reg, Base)
assert issubclass(Registered, Base)
